// ===== Бодит мэдээнүүд (2026-11-05) — өдөр бүр шинэчлэгдэнэ =====
const ARTICLES = [
  {id:1, cat:"uls-tor", title:"Засгийн газар: Төрийн албан хаагчдын цалин, тэтгэврийг нэмэгдүүлж, хүнд сурталтай дарга нарыг чөлөөллөө", titleEn:"Government: public servants' salaries and pensions raised, officials blamed for red tape dismissed", time:"15 мин", timeEn:"15 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Mongolian%20Parliament%201.JPG?width=1000", text:"Засгийн газрын ээлжит хуралдаан 2026 оны арваннэгдүгээр сарын 4-нд болж, нийгэм, эдийн засгийн 20 асуудлыг хэлэлцлээ. Хуралдаанаас гарсан шийдвэрийн талаар Гэр бүл, хөдөлмөр, нийгмийн хамгааллын сайд Т.Аубакир мэдээлэл хийхдээ тэтгэвэр, тэтгэмжийн хэмжээг шинэчлэн тогтоох, төрийн үйлчилгээний албан хаагчдын цалингийн доод хэмжээг тогтоох тухай хоёр тогтоол баталсан гэж мэдэгдэв. Ингэснээр өмнө нь цалин нь нэмэгдээгүй байсан төрийн үйлчилгээний зарим албан хаагчдын цалин тодорхой хэмжээгээр нэмэгдэхээр болж байна.\n\nСайдын мэдээлснээр 2025 оны байдлаар 4,330 төрийн байгууллагад 213 мянган төрийн албан хаагч ажиллаж байгаа бөгөөд цалин нэмэгдүүлэхэд 2026 оны төсвийн тодотголд 170.1 тэрбум төгрөг суулгажээ. Улаанбаатар хотод ажилладаг төрийн албан хаагчийн цалин хөдөө орон нутагт ажилладаг ижил түвшний албан хаагчийн цалингаас ялгаатай байдаг асуудлыг ч энэ шийдвэрт харгалзан үзсэн байна. Эрүүл мэндийн салбарын хувьд цалинг арваннэгдүгээр сарын 1-нээс нэмэгдүүлэхээр тооцсон бөгөөд эрчимт эмчилгээ, мэдээгүйжүүлгийн их эмчийн цалин 2 сая 128 мянган төгрөгөөс 2 сая 456 мянган төгрөг болж, 328 мянган төгрөгөөр нэмэгдэнэ. Ахмад настнуудын суурь тэтгэвэр ч арваннэгдүгээр сарын 1-нээс нэмэгдэж бодогдож эхэллээ.\n\nМөн хуралдаанаар хүнд суртал, хууль зөрчсөн асуудлаар хариуцлага ярих болов. Ерөнхий сайд Н.Учрал аудитын байгууллагаас 113 албан тушаалтанд хариуцлага тооцох албан шаардлага ирснийг дурдаж, хэнд ямар хариуцлага тооцсон талаар ирэх долоо хоногт олон нийтэд мэдээлэхийг Засгийн газрын Хэрэг эрхлэх газрын удирдлагуудад үүрэг болголоо. Татварын ерөнхий газрын дарга Б.Цогтнаран, Мал эмнэлгийн ерөнхий газрын дарга Х.Алтангэрэл, Хөрөнгө оруулалт, худалдааны газрын дарга Б.Зандан нарыг хяналтын байгууллага, Төрийн албаны зөвлөлөөс ирүүлсэн мэдэгдэлд үндэслэн ажлаас нь чөлөөлсөн байна. Түр томилгоотой байгаа төрийн нарийн бичгийн дарга, агентлагийн даргын албан тушаалд өнөөдрөөс нээлттэй сонгон шалгаруулалт зарлажээ.", textEn:"The Cabinet held its regular meeting on November 4, 2026, discussing 20 social and economic issues. Family, Labour and Social Protection Minister T. Aubakir said the government adopted two resolutions: one updating pension and benefit amounts, and one setting the minimum salary for public service employees. As a result, some public service employees whose salaries had not previously risen will now receive a defined increase.\n\nAccording to the minister, 213,000 public servants work in 4,330 state organisations as of 2025, and 170.1 billion tugriks were included in the 2026 budget amendment to fund the salary increases. The decision also took into account the gap between salaries of public servants in Ulaanbaatar and those in the same positions in rural areas. In health care, salaries are to be raised from November 1: an intensive care and anaesthesiology doctor's salary rises from 2,128,000 to 2,456,000 tugriks, an increase of 328,000 tugriks. The basic pension for elderly citizens also began to be calculated at the higher level from November 1.\n\nThe meeting also addressed accountability for red tape and legal violations. Prime Minister N. Uchral noted that the audit authority had demanded accountability for 113 officials, and instructed the Cabinet Secretariat leadership to inform the public next week about who was held responsible and how. The directors of the General Department of Taxation, B. Tsogtnaran, the Veterinary Department, Kh. Altangerel, and the Investment and Trade Agency, B. Zandan, were dismissed on the basis of notices from oversight bodies and the Civil Service Council. Open competitions were announced from today for acting state secretary and agency director posts."},
  {id:2, cat:"uls-tor", title:"ТББХ: Чингис хааны хөргийг архи, тамхинд ашиглахгүй байх саналыг дэмжив", titleEn:"Parliamentary committee backs ban on using Chinggis Khaan's portrait on alcohol and tobacco", time:"30 мин", timeEn:"30 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Mongolia%20Parliament%20Building.JPG?width=760", text:"Улсын Их Хурлын Төрийн байгуулалтын байнгын хороо 2026 оны арваннэгдүгээр сарын 4-нд хуралдаж, Их Монгол Улс байгуулагдсаны 820 жилийн ойг тохиолдуулан Их Эзэн Чингис хааны төрт ёсны өв уламжлалыг дээдлэн мөнхжүүлэх тухай Улсын Их Хурлын тогтоолын төслийг хэлэлцэн дэмжлээ. Тогтоолын төслийг Улсын Их Хурлын дарга С.Бямбацогт санаачлан боловсруулсан бөгөөд гишүүд уг төслийг бүхэлд нь дэмжиж, чуулганы нэгдсэн хуралдаанаар хэлэлцүүлэх нь зүйтэй гэж үзжээ.\n\nХэлэлцүүлгийн үеэр Улсын Их Хурлын гишүүн Л.Гантөмөр дэмжиж буйгаа илэрхийлж, зарчмын зөрүүтэй санал гаргасан байна. Тодруулбал, Чингис хааны хөргийг архи, тамхинд хэрэглэхгүй байх тухай саналыг байнгын хорооны хуралдаанд оролцсон гишүүдийн олонх дэмжлээ. Энэ нь хааны нэр төр, түүхэн үнэ цэнийг хамгаалах зорилготой тогтоолын төслийн нэг хэсэг болж байна.\n\nТогтоолын төсөлд Чингис хааны асуудлыг шинжлэх ухааны үндэслэлтэй судлах, үр хойчдоо өвлүүлэн үлдээх, гадаад улсад байгаа бичвэр, эш хөргийг эх орондоо авч ирэх зэрэг арга хэмжээ тусгагджээ. Мөн Их хааны нэрээр нэрлэгдсэн онцгой албан татвар төлдөг бүтээгдэхүүний тодорхой хувийг Чингис хаан санд төвлөрүүлж, сангийн хөрөнгөөр эх түүхээ сурталчлан таниулах ажлыг зохион байгуулах эрх зүйн орчныг бүрдүүлэхээр тусгасан байна. Төслийн эхлэл болгон арваннэгдүгээр сардаа багтаан БНСУ-д ганц хувь байдаг Тогоон төмөр хааны үеийн хууль цаазын бичгийг Монгол Улсдаа авч ирж, Чингис хааны музейд байршуулан олон нийтийн хүртээл болгохыг зорьж байгаа аж. Арваннэгдүгээр сарын 10-нд Улсын Их Хурлын хүндэтгэлийн чуулганыг хуралдуулахаар дарга захирамж гаргаад байна.", textEn:"The State Structure Standing Committee of the State Great Khural met on November 4, 2026, and backed a draft resolution on honouring and perpetuating the state heritage of Chinggis Khaan on the 820th anniversary of the founding of the Great Mongol State. The draft, initiated by Speaker S. Byambatsogt, was supported in full by members, who agreed it should be discussed at a plenary session.\n\nDuring the discussion, Member of Parliament L. Gantomor expressed support and tabled a principled amendment: that Chinggis Khaan's portrait should not be used on alcohol or tobacco products. A majority of committee members present supported that proposal. It forms part of the draft resolution's aim to protect the Khaan's honour and historical value.\n\nThe draft also covers studying Chinggis Khaan on a scientific basis, passing his legacy to future generations, and bringing texts and portraits held abroad back to Mongolia. It provides for creating the legal framework to channel a share of the excise tax from products named after the Great Khaan into a Chinggis Khaan Fund, whose resources would promote national history. As a first step, the single surviving copy in South Korea of a legal code from the Toghon Temur period is to be brought to Mongolia within November and displayed at the Chinggis Khaan Museum. A ceremonial session of parliament has been called for November 10."},
  {id:3, cat:"niigem", title:"Шатахууны хомсдол, оочир дараалал үргэлжилсээр байна", titleEn:"Fuel shortage and queues continue", time:"45 мин", timeEn:"45 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Bishkek%2003-2016%20img21%20Akhunbaev%20Street%20petrol%20station.jpg?width=760", text:"Өнгөрсөн долоодугаар сарын сүүлээр эхэлсэн шатахууны хомсдол, оочир дараалал одоо ч үргэлжилж байна. МҮОНРТ-ийн арваннэгдүгээр сарын 4-ний мэдээллээр улсын хэмжээнд АИ-92 автобензин 10 хоног, дизель түлш 28 хоног, онгоцны түлш 36 хоногийн нөөцтэй байгаа аж. Гэвч нөөц байгаа мэдээ иргэдийн өдөр тутмын бодит байдалтай зөрж, шатахуун түгээх станцуудад урт оочир дараалал үүсч, хэзээ хэвийн болох нь тодорхойгүй хэвээр байна.\n\nБаянгол дүүргийн 23 дугаар хороо, Зурагтын шинэ эцсийн орчимд байрлах «Сод Монгол», «Super 92» зэрэг шатахуун түгээх станцуудад автомашины урт цуваа үүссэн байдалтай байна. Шатахуунд оочирлож байгаа жолооч нар оочир дараалал хэдэн сар багасахгүй үргэлжилж байна гэж ярьжээ. Зарим иргэн өнөөдөр оочирлоод шатахуунаа авчихвал таван хоног авахгүй гэсэн санаатай байгаа тухайгаа хэлсэн байна. Ингэснээр шатахуунд оочирлох нь олон жолоочийн хувьд өдөр тутмын хамгийн гол ажлын нэг болоод байна.\n\nШатахууны шуурхай штабаас арваннэгдүгээр сарын 3-нд мэдээлэл хийхдээ нийлүүлэлтийг нэмэгдүүлэхээр нийт 92 мянган тонн шатахуун импортлохоор захиалгыг баталгаажуулсан гэж мэдэгдсэн. Үүнд ОХУ-аас 70 мянган тонн, БНСУ-аас 12 мянган тонн, БНХАУ-аас 8 мянган тонн, Казахстан Улсаас 3 мянган тонн шатахуун багтаж байна. ОХУ-ын Ангарскийн нефть боловсруулах үйлдвэрээс аравдугаар сард захиалсан 57 мянган тонн бүтээгдэхүүнээс 51 мянган тонн нь ачигдаж, одоогоор замд 5,700 тонн шатахуун тээвэрлэгдэж байна. Арав, арваннэгдүгээр сар нь зуны түлшнээс өвлийн түлшинд шилждэг үе бөгөөд өвлийн түлшний нөөц хангалттай бүрдсэн гэж албаныхан мэдээллээ.", textEn:"The fuel shortage and queues that began in late July are still continuing. According to Mongolian National Broadcaster on November 4, nationwide reserves stand at 10 days for AI-92 petrol, 28 days for diesel and 36 days for aviation fuel. Yet the reported reserves contrast with citizens' daily reality: long queues persist at petrol stations, and it remains unclear when the situation will return to normal.\n\nLong lines of cars have formed at stations such as Sod Mongol and Super 92 near the new Zurgin terminal in Bayangol district's 23rd khoroo. Drivers queuing for fuel say the queues have not eased for months. Some say that if they queue and fill up today, they do so with the intention of not needing fuel for five days. Queuing for fuel has thus become one of the main daily tasks for many drivers.\n\nThe fuel rapid-response headquarters said on November 3 that import orders for a total of 92,000 tonnes of fuel have been confirmed to increase supply: 70,000 tonnes from Russia, 12,000 from South Korea, 8,000 from China and 3,000 from Kazakhstan. Of the 57,000 tonnes ordered in October from Russia's Angarsk refinery, 51,000 tonnes have been shipped and 5,700 tonnes are currently in transit. October and November are the transition from summer to winter fuel, and officials say winter fuel reserves are sufficient."},
  {id:4, cat:"ediin-zasag", title:"Нийслэлд зургаан төрлийн үйлчилгээний албан татварыг нэг хувь болгон бууруулна", titleEn:"Capital to cut city tax on six service types to one percent", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Ulaanbaatar%20Ulaanbaatar%20WMID8133454.jpg?width=760", text:"Нийслэлийн иргэдийн Төлөөлөгчдийн Хурал дахь Эдийн засаг, төсөв, хөрөнгө оруулалтын хорооны ээлжит хуралдаан 2026 оны арваннэгдүгээр сарын 4-нд болж, авто зам ашигласны төлбөр, хотын албан татварын хувь хэмжээ, зээллэгийн санхүүжилтээр хэрэгжүүлэх төсөл, арга хэмжээ болон нийслэлийн өмчийн барилга байгууламжтай холбоотой асуудлыг хэлэлцлээ.\n\nХуралдаанаар хотын албан татварын хувь хэмжээг шинэчлэн тогтоох тухай асуудлыг нийслэлийн Засаг даргын Эдийн засгийн хөгжил, дэд бүтцийн асуудал хариуцсан нэгдүгээр орлогч Б.Мөнхбат танилцуулав. Тогтоолын төслөөр нийслэлийн нутаг дэвсгэрт үйл ажиллагаа явуулдаг зургаан төрлийн үйлчилгээний албан татварыг одоогийн хоёр хувиас нэг хувь болгон бууруулж, 2027 оны нэгдүгээр сарын 1-нээс хэрэгжүүлэхээр тусгажээ. Мөн «Нийслэл хотын албан татвар» гэсэн нэршлийг «Хотын албан татвар» болгон өөрчлөхөөр төлөвлөсөн байна.\n\nХуралдаанд оролцсон төлөөлөгчид татварын хувь хэмжээг бууруулснаар аж ахуйн нэгж, эцсийн хэрэглэгчдэд ямар үр өгөөж гарах, үйлчилгээний үнэ тариф буурах эсэхийг тодруулсан байна. Авто зам ашигласны төлбөрийн зохицуулалтыг боловсронгуй болгох асуудлыг нийслэлийн Засаг даргын Замын хөгжлийн төсөл, хөтөлбөрийн зохицуулагч Л.Хосбаяр танилцуулсан бөгөөд сүүлийн таван жилийн өрийн барагдуулалт, үлдэгдлийг нарийвчлан гаргах шаардлагатайг төлөөлөгчид онцолжээ. Мөн «Эмээлт эко аж үйлдвэрийн парк» ХК-ийн гүйцэтгэх захирал Б.Мягмар дэд бүтцийн бүтээн байгуулалтын талаар танилцуулсан байна. Хан-Уул дүүргийн 20 дугаар хорооны аж үйлдвэрийн бүсэд арьс ширний 28, ноосны гурван үйлдвэр үйл ажиллагаа явуулж байгаа бөгөөд тэдгээрийг нүүлгэн шилжүүлэх хүрээнд паркийн дэд бүтцийг байгуулж байна.", textEn:"The Economy, Budget and Investment Committee of the Ulaanbaatar Citizens' Representatives' Khural held its regular meeting on November 4, 2026, discussing road-use fees, city tax rates, loan-financed projects and measures, and capital-owned buildings.\n\nFirst Deputy Governor B. Munkhbat, responsible for economic development and infrastructure, presented the proposal to update city tax rates. Under the draft resolution, the city tax on six types of services operating in the capital would fall from the current two percent to one percent, taking effect from January 1, 2027. The name «Capital City Tax» would also be changed to «City Tax».\n\nRepresentatives asked what benefit businesses and end consumers would gain from the cut, and whether service prices and tariffs would fall. Road development project coordinator L. Khosbayar presented improvements to road-use fee regulation, with representatives stressing the need for detailed figures on debt repayment and balances over the past five years. The CEO of Emelt Eco Industrial Park, B. Myagmar, also reported on infrastructure construction: 28 leather and three wool factories operate in the industrial zone of Khan-Uul district's 20th khoroo, and the park's infrastructure is being built as part of their relocation."},
  {id:5, cat:"ediin-zasag", title:"БНСУ-тай хүнс, хөдөө аж ахуйн хамтын ажиллагааг өргөжүүлж, экспортыг хөнгөвчлөхөөр ярилцлаа", titleEn:"Mongolia and South Korea discuss wider food and agriculture cooperation and easier exports", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Banaue%20Philippines%20Batad-Rice-Terraces-02.jpg?width=760", text:"Хүнс, хөдөө аж ахуй, хөнгөн үйлдвэрийн сайд Ц.Идэрбат БНСУ-аас Монгол Улсад суугаа Онц бөгөөд Бүрэн эрхт Элчин сайд Чой Жин Воныг Төрийн ордонд хүлээн авч уулзан, салбарын хамтын ажиллагааны талаар санал солилцлоо. Сайд уулзалтын эхэнд БНСУ-аас хэрэгжүүлж ирсэн төсөл хөтөлбөрүүдэд талархал илэрхийлж, хамтын ажиллагааг бодит үр дүнд хүргэнэ гэдэгт итгэж буйгаа хэлжээ.\n\nМонгол Улсын хувьд БНСУ нь эдийн засаг, технологи, хөдөө аж ахуйн салбарт хамтран ажиллах бодит боломж бүхий «Стратегийн түншлэл»-тэй чухал түнш юм. БНСУ-ын Олон улсын хамтын ажиллагааны байгууллага, Солонгосын хөдөө аж ахуйн төсөл хэрэгжүүлэх байгууллагаар дамжуулан хүнсний аюулгүй байдлын удирдлагын тогтолцоо байгуулах, малын гаралтай бүтээгдэхүүний аюулгүй байдлын тогтолцоо байгуулах, Халх голын бүсийн хөдөө аж ахуйн хөгжил, ухаалаг хүлэмжийн цогцолбор байгуулах зэрэг олон төсөл хэрэгжиж ирсэн нь салбарын хөгжилд бодит үр дүнгээ өгөөд байгаа аж.\n\nСайд БНСУ-ын Ерөнхийлөгч И Жэ Мёны Монгол Улсад хийсэн төрийн айлчлалын хүрээнд байгуулсан харилцан ойлголцлын гурван санамж бичгийн хэрэгжилтийг хангахад идэвхтэй хамтран ажиллахаа илэрхийлсэн байна. Мөн Монгол Улс хөдөө аж ахуйн бүтээгдэхүүнийг экспортын чиг баримжаатай хөгжүүлэх бодлого баримталж буйг онцлоод, дотоодод тарьж ургуулсан гурвалжин будаа, цагаан будаа, ногоон тэжээл, арвай, улаанбуудайн гурил, эмийн ургамлыг БНСУ-д экспортлоход хорио цээрийн стандарт, импортын квотыг хөнгөвчлөх, тэр дундаа гурвалжин будааг бага татварын квотод хамруулахад хамтран ажиллах шаардлагатайг тэмдэглэлээ. Элчин сайдын хэлснээр махны экспортын тухайд хоёр улсын хооронд байгуулж буй Эдийн засгийн түншлэлийн хэлэлцээр хүлээгдэж байгаа бөгөөд хэлэлцээр албажсанаар Монголын үхрийн махны 25-40 хувийн татвар таван жилийн хугацаанд бүрэн чөлөөлөгдөх боломжтой аж.", textEn:"Food, Agriculture and Light Industry Minister Ts. Iderbat received South Korean Ambassador Choi Jin-won at the State Palace and exchanged views on sectoral cooperation. At the start of the meeting, the minister thanked South Korea for its past projects and programmes and expressed confidence that cooperation would produce tangible results.\n\nFor Mongolia, South Korea is an important partner with a Strategic Partnership offering real scope for cooperation in the economy, technology and agriculture. Through the Korea International Cooperation Agency and the Korea Programme on International Agriculture, projects such as building food safety management systems, livestock product safety systems, agricultural development in the Khalkh Gol region and smart greenhouse complexes have already delivered tangible results for the sector.\n\nThe minister said Mongolia would actively cooperate in implementing the three memoranda of understanding signed during South Korean President Lee Jae-myung's state visit to Mongolia. He stressed Mongolia's policy of developing agricultural products with an export orientation, and the need to cooperate on easing quarantine standards and import quotas for exporting domestically grown buckwheat, rice, green fodder, barley, wheat flour and medicinal plants to South Korea, including placing buckwheat under a low-tariff quota. According to the ambassador, an Economic Partnership Agreement between the two countries is awaited for meat exports; once in force, it could fully remove the 25-40 percent tariff on Mongolian beef over five years."},
  {id:6, cat:"delhii", title:"АНУ-ын завсрын сонгуульд Ардчилсан нам Конгрессын хяналтыг авлаа", titleEn:"Democrats take control of Congress in US midterm elections", time:"2 цаг", timeEn:"2 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Capitol%20Building%20Full%20View.jpg?width=760", text:"АНУ-д 2026 оны арваннэгдүгээр сарын 3-нд болсон завсрын сонгуулийн дүнгээр Ардчилсан нам Конгрессын хоёр танхимын хяналтыг авлаа. Энэ нь 2023 оноос хойш анх удаа Ардчилсан нам Конгрессыг бүрэн хянах болсон явдал бөгөөд сонгогчид Ерөнхийлөгч Дональд Трампын Бүгд найрамдах намыг татгалзсан гэж олон хэвлэл дүгнэж байна.\n\nМэдээллээр Ардчилсан нам Сенатад долоон суудал эргүүлэн авсан бөгөөд Техас, Айова, Канзас, Хойд Каролина, Өмнөд Каролина, Охайо зэрэг мужуудад ялалт байгуулжээ. Төлөөлөгчдийн танхимд ч Флоридагийн дор хаяж гурван тойрог, Пенсильванид Бүгд найрамдах намын дөрвөн гишүүнийг ялсан байна. Шинэ Конгресс 2027 оны нэгдүгээр сарын 3-нд хуралдах бөгөөд Нью-Йоркийн төлөөлөгч Хаким Жеффрис Танхимын анхны хар арьст спикер болох төлөвтэй байна.\n\nСонгуулийн үр дүнд Трампын Ирантай хийж буй дайн болон эдийн засгийн бодлогод сонгогчдын дургүйцэл нөлөөлсөн гэж ажиглагчид үзэж байна. Ираны хэлэлцээний ахлах төлөөлөгч хүртэл америкчууд «дайнд үгүй» гэж саналаа өгсөн гэж мэдэгджээ. Харин хөрөнгийн зах зээл Ардчилсан намын ялалтыг аль хэдийн үнэлж тооцсон байсан тул огцом хөдлөөгүй гэж мэдээлж байна. Бүгд найрамдах намын зарим гишүүн ялагдлыг Трамптай холбон шүүмжилж байгаа бол Ерөнхийлөгч асан Барак Обама Ардчилсан намын түүхэн ялалтыг сайшааж, хүмүүсийг нэгтгэдэг улс төрийг уриалжээ.", textEn:"In the United States midterm elections held on November 3, 2026, the Democratic Party won control of both chambers of Congress. It is the first time since 2023 that Democrats have held full control of Congress, and many outlets describe the result as voters rejecting President Donald Trump's Republican Party.\n\nDemocrats flipped seven Senate seats, winning in states including Texas, Iowa, Kansas, North Carolina, South Carolina and Ohio. In the House, they also won at least three districts in Florida and unseated four Republican incumbents in Pennsylvania. The new Congress convenes on January 3, 2027, and New York Representative Hakeem Jeffries is expected to become the first Black Speaker of the House.\n\nObservers say voter discontent with Trump's war with Iran and his economic policies influenced the result. Iran's chief negotiator even said Americans voted «no to war». Stock markets, by contrast, barely moved, having already priced in the Democratic sweep. Some Republicans blamed Trump for the defeat, while former President Barack Obama praised the historic Democratic gains and called for politics that brings people together."},
  {id:7, cat:"delhii", title:"Техаст 1988 оноос хойших анхны Ардчилсан сенатор, Мичиганд анхны лалын шашинт сенатор сонгогдлоо", titleEn:"Texas elects first Democratic senator since 1988; Michigan elects first Muslim senator", time:"2 цаг", timeEn:"2 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Capitol%20at%20Dusk%202.jpg?width=760", text:"АНУ-ын завсрын сонгууль түүхэн хэд хэдэн үр дүнг авчирлаа. Техаст Жеймс Таларико Сенатын суудалд ялж, 1988 оноос хойш тус мужаас сонгогдсон анхны Ардчилсан сенатор болсон байна. Техас нь өмнө нь Трамп гурван удаа дараалан ялсан муж байсан тул энэ ялалт онцгой анхаарал татаж байна.\n\nМичиганд Абдул Эль-Саед Сенатын сонгуульд ялж, АНУ-ын Сенатад сонгогдсон анхны лалын шашинт америк хүн боллоо. Түүний ялалт нь Ардчилсан намын Сенатад эргүүлэн авсан долоон суудлын нэг бөгөөд сонгуулийн шөнийн хамгийн их яригдсан үр дүнгийн нэг болжээ. Мөн Флорида муж анхны хар арьст амбан захирагчаа сонгосон бол Өмнөд Каролинад Анни Эндрюс ялж, тус мужийн бараг гучин жилийн дараа сонгогдсон анхны Ардчилсан сенатор болсон байна.\n\nЭдгээр ялалт нь Ардчилсан нам Конгрессын хяналтыг авсан өргөн хүрээний давалгааны нэг хэсэг юм. Айовад Жош Турек, Хойд Каролинад Рой Купер зэрэг нэр дэвшигчид ч Сенатад ялалт байгуулжээ. Сонгуулийн ажиглагчид эдгээр үр дүнг сонгогчдын өөрчлөлтийн төлөөх хүчтэй дохио гэж тайлбарлаж байгаа бөгөөд шинэ сенаторууд 2027 оны нэгдүгээр сард тангараг өргөх төлөвтэй байна.", textEn:"The US midterm elections produced several historic results. In Texas, James Talarico won a Senate seat, becoming the first Democrat elected to the Senate from that state since 1988. The victory drew particular attention because Texas had voted for Trump three times in a row.\n\nIn Michigan, Abdul El-Sayed won his Senate race, becoming the first Muslim American ever elected to the US Senate. His win was one of the seven Senate seats flipped by Democrats and one of the most discussed results of election night. Florida also elected its first Black governor, while in South Carolina Annie Andrews won to become the state's first Democratic senator in almost three decades.\n\nThese victories were part of the broader wave that gave Democrats control of Congress. Candidates such as Josh Turek in Iowa and Roy Cooper in North Carolina also won Senate seats. Election observers describe the results as a strong signal of voters' desire for change, and the new senators are expected to be sworn in in January 2027."},
  {id:8, cat:"delhii", title:"Испанийн тээврийн сайд 69 хүний аминд хүрсэн галт тэрэгний ослын дараа огцрох санал гаргалаа", titleEn:"Spain's transport minister offers to resign after train crashes kill 69", time:"3 цаг", timeEn:"3 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Tarragona%20train%20station.01.jpg?width=760", text:"Испанийн тээврийн сайд 69 хүний аминд хүрсэн галт тэрэгний ослын дараа огцрох саналаа гаргалаа. Урда хот орчимд болсон осол нь тус улсад богино хугацаанд гарсан хоёр дахь төмөр замын гамшиг болсон бөгөөд ослын дараа олон нийт, улс төрийн хүрээнд хариуцлага нэхэх дуу хоолой хүчтэй өрнөж байна.\n\nОслын улмаас олон арван хүн амиа алдаж, олон хүн шархадсан бөгөөд аврах ажиллагаа, хохирогчдыг таних ажил үргэлжилж байна. Тээврийн сайдын огцрох санал нь ослын шалтгаан, төмөр замын аюулгүй байдлын талаарх маргааны голд гарч байгаа бөгөөд засгийн газар мөрдөн шалгах ажиллагааг эрчимжүүлэхээ мэдэгджээ.\n\nЭнэ осол нь Испанийн төмөр замын сүлжээний аюулгүй байдал, засвар үйлчилгээ, хяналтын тогтолцоонд анхаарал хандуулж байна. Ойрын өдрүүдэд ослын шалтгааны талаарх албан ёсны дүгнэлт гарч, хариуцлага хүлээх асуудал улс төрийн хэлэлцүүлгийн гол сэдэв хэвээр байх төлөвтэй байна.", textEn:"Spain's transport minister has offered to resign after train crashes that killed 69 people. The crash near Urda was the country's second rail disaster in a short period, and it has fuelled strong public and political demands for accountability.\n\nDozens of people were killed and many more injured, with rescue work and victim identification continuing. The minister's resignation offer comes amid debate over the causes of the crash and railway safety, and the government has said it will step up the investigation.\n\nThe disaster has focused attention on the safety, maintenance and oversight of Spain's railway network. An official account of the causes is expected in the coming days, and the question of accountability is set to remain at the centre of political debate."},
  {id:9, cat:"delhii", title:"Трамп: АНУ Израильд жилд олгодог 4 тэрбум долларын цэргийн тусламжийг оны эцсээр зогсооно", titleEn:"Trump: US to end $4 billion annual military aid to Israel by year-end", time:"3 цаг", timeEn:"3 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Old%20City%20Walls%20and%20Tower%20of%20David%20in%20Jerusalem%20(2019)%2003.jpg?width=760", text:"АНУ-ын Ерөнхийлөгч Дональд Трамп Израильд жилд олгодог 3.8 тэрбум долларын цэргийн тусламжийг оны эцсээр зогсооно гэж мэдэгдлээ. Энэ нь Обамагийн үед байгуулсан арван жилийн хугацаатай тохиролцоог хугацаанаас нь өмнө дуусгах алхам бөгөөд Израилын албан тушаалтнуудыг цочирдуулсан гэж мэдээлж байна.\n\nТрампын мэдэгдэл нь Израилын Ерөнхий сайд Биньямин Нетаньяхугийн эвсэл парламентын олонхоо алдсанаас хэдхэн хоногийн дараа гарч байгаа нь анхаарал татаж байна. Нетаньяху тусламжийг зогсоохыг зөвшөөрсөн гэж Трамп мэдэгдсэн боловч Израилын талын байр суурь, цаашид аюулгүй байдлын хамтын ажиллагаа хэрхэн үргэлжлэх нь тодорхойгүй хэвээр байна.\n\nАНУ-ын Израильд үзүүлэх цэргийн тусламж нь хоёр улсын харилцааны гол тулгуур байсаар ирсэн бөгөөд энэ шийдвэр нь Ойрхи Дорнодын аюулгүй байдал, АНУ-ын гадаад бодлогын чиглэлд томоохон өөрчлөлт болж магадгүй гэж ажиглагчид үзэж байна. Тусламж зогссоны дараа Израилын батлан хамгаалах төсөв, АНУ-аас зэвсэг худалдан авах гэрээнүүдэд ямар нөлөө гарахыг ойрын саруудад харах боломжтой болно.", textEn:"US President Donald Trump has said the United States will end its roughly $3.8 billion annual military aid to Israel by the end of the year. The move would cut short the ten-year arrangement agreed in the Obama era, and is reported to have startled Israeli officials.\n\nTrump's announcement came just days after Israeli Prime Minister Benjamin Netanyahu's bloc lost its parliamentary majority, adding to its significance. Trump said Netanyahu agreed to ending the aid, but Israel's position and how security cooperation will continue remain unclear.\n\nUS military aid to Israel has long been a pillar of the two countries' relationship, and observers say the decision could mark a major shift in Middle East security and US foreign policy. Its effects on Israel's defence budget and on arms purchase agreements with the US will become clearer in the coming months."},
  {id:10, cat:"delhii", title:"Хятад 40 гаруй улсад визгүй зорчих бодлогоо 2026 оны эцэс хүртэл сунгалаа", titleEn:"China extends visa-free travel for more than 40 countries until end of 2026", time:"4 цаг", timeEn:"4 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Shanghai%20skyline%20from%20the%20bund.jpg?width=760", text:"Хятад улс 40 гаруй улсад олгодог нэг талын визгүй зорчих бодлогоо 2026 оны арванхоёрдугаар сарын 31 хүртэл сунгахаар шийдвэрлэлээ. Энэ тухай Хятадын Гадаад хэргийн яамны хэвлэлийн төлөөлөгч Мао Нин мэдэгдсэн бөгөөд Швед улсыг 2025 оны арваннэгдүгээр сарын 10-наас 2026 оны арванхоёрдугаар сарын 31 хүртэл визгүй схемд шинээр хамруулахаар шийдвэрлэсэн байна.\n\nВизгүй бодлого нь аялал жуулчлал, бизнес, соёлын солилцоог дэмжих зорилготой бөгөөд Хятад улс сүүлийн жилүүдэд энэ бодлогыг аажмаар өргөжүүлж ирсэн. Швед шинээр нэмэгдсэнээр визгүй зорчих боломжтой улсын тоо улам нэмэгдэж, Европ, Азийн бусад улстай харилцаа улам нягтрах төлөвтэй байна.\n\nМөн Шанхай хотноо арваннэгдүгээр сарын 5-10-нд болох найм дахь удаагийн Хятадын олон улсын импортын үзэсгэлэнд (CIIE) зарим улсын удирдагчид оролцохоор төлөвлөж байна. Үзэсгэлэн нь Хятадын зах зээлд гадаадын бараа бүтээгдэхүүн нэвтрэх гол талбар болсон бөгөөд визний хөнгөлөлттэй хамт гадаад худалдаа, хөрөнгө оруулалтыг дэмжих дохио болж байна гэж ажиглагчид үзэж байна.", textEn:"China has decided to extend its unilateral visa-free travel policy for more than 40 countries until December 31, 2026. Foreign ministry spokesperson Mao Ning announced the extension, adding that Sweden will newly join the visa-free scheme from November 10, 2025, until December 31, 2026.\n\nThe visa-free policy aims to support tourism, business and cultural exchange, and China has gradually expanded it in recent years. Sweden's addition further increases the number of countries whose citizens can travel visa-free, and is expected to deepen ties with other European and Asian countries.\n\nA number of foreign leaders are also set to attend the eighth China International Import Expo (CIIE) in Shanghai from November 5 to 10. The expo has become a key platform for foreign goods to enter the Chinese market, and observers see it, together with the visa easing, as a signal of support for foreign trade and investment."},
  {id:11, cat:"delhii", title:"Вьетнамын төв хэсэгт үер 37 хүний аминд хүрч, Афганистанд газар хөдлөлт 24 хүнийг хөнөөлөө", titleEn:"Central Vietnam floods kill 37; Afghanistan earthquake kills 24", time:"4 цаг", timeEn:"4 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Flooded%20building%20and%20tree%20trunk%20in%20the%20muddy%20water%20of%20the%20Mekong%20in%20Si%20Phan%20Don,%20Laos,%20September%202019.jpg?width=760", text:"Вьетнамын төв хэсэгт хүчтэй бороо, үерийн улмаас амиа алдсан хүний тоо 37-д хүрч, таван хүн сураггүй, 78 хүн шархадсан гэж Вьетнамын гамшгийн менежментийн байгууллага мэдээллээ. Үер олон аймагт зам, гэр орон, тариалангийн талбайг сүйтгэж, аврах ажиллагаа үргэлжилж байна. Орон нутгийн удирдлагууд үерийн ус буух хүртэл аюултай бүсээс хол байхыг иргэдэд анхааруулжээ.\n\nҮүний зэрэгцээ Афганистаны хойд хэсэгт болсон газар хөдлөлтийн улмаас 24 хүн амиа алдаж, 630 гаруй хүн шархадсан байна. Шархадсан хүмүүсийн ихэнх нь хөнгөн гэмтэл авсан гэж Афганистаны гамшгийн менежментийн байгууллага мэдээлсэн бөгөөд нурсан барилга, эвдэрсэн замд тусламж хүргэх ажил үргэлжилж байна.\n\nЭдгээр хоёр гамшиг нь Азийн бүс нутагт байгалийн гамшгийн эрсдэл өндөр хэвээр байгааг харуулж байна. Вьетнамд бороо үргэлжилбэл үерийн аюул нэмэгдэж болзошгүй тул урьдчилсан мэдээг тогтмол дагах шаардлагатай байгаа бол Афганистанд газар хөдлөлтийн дараах чичиргээ, барилгын аюулгүй байдлыг шалгах ажил чухал хэвээр байна.", textEn:"In central Vietnam, heavy rain and flooding have killed 37 people, with five missing and 78 injured, according to Vietnam's disaster management authority. Floods have damaged roads, homes and farmland across several provinces, and rescue operations are continuing. Local authorities have warned residents to stay away from dangerous areas until floodwaters recede.\n\nAt the same time, an earthquake in northern Afghanistan has killed 24 people and injured more than 630. Most of the injured suffered minor injuries, according to Afghanistan's disaster management authority, and work to deliver aid amid collapsed buildings and damaged roads is continuing.\n\nThe two disasters show that natural disaster risk remains high across Asia. In Vietnam, continued rain could worsen flooding, making it essential to follow forecasts regularly, while in Afghanistan checking for aftershocks and building safety remains important."},
  {id:12, cat:"sport", title:"«Алтанцом»-ын барилдаан бямба гарагт эхэлнэ", titleEn:"Altantsom wrestling league starts on Saturday", time:"5 цаг", timeEn:"5 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Mongolian%20Wrestling.jpg?width=760", text:"2026-2027 оны «Алтанцом»-ын барилдаан энэ бямба гарагт буюу арваннэгдүгээр сарын 7-нд Бөхийн өргөөнд эхэлнэ. Өмнө нь найман баг оролцож байсан бол энэ удаа үндэсний шилдэг компаниуд болон аймгийн дэвжээдийг төлөөлж долоон баг өрсөлдөхөөр болжээ.\n\nБагуудаас Дархан аварга Н.Батсуурь ахлагчтай «Увс нуур» дэвжээ, Даян аварга Б.Орхонбаяр ахлагчтай АПУ СКАЙТЕЛ, Улсын гарди М.Лхагвагэрэл ахлагчтай «Эв монгол» баг зэрэг хүчтэй бүрэлдэхүүнүүд оролцоно. Багуудын ахлагчдын нэрс нь энэ улирлын барилдаан өрсөлдөөнтэй, үзүүштэй болохыг харуулж байна.\n\n«Алтанцом» нь үндэсний бөхийн багийн барилдааны томоохон тэмцээн бөгөөд үзэгчид багуудын өрсөлдөөнийг Бөхийн өргөөнд шууд үзэх боломжтой. Эхний тойргийн барилдаанаас эхлэн багууд улирлын турш оноо цуглуулж, шилдгүүд тодорно. Бөхийн хорхойтнууд бямба гарагийн нээлтийн барилдааныг тэсэн ядан хүлээж байна.", textEn:"The 2026-2027 Altantsom wrestling league starts this Saturday, November 7, at the Wrestling Palace. While eight teams took part previously, seven teams representing leading national companies and provincial clubs will compete this time.\n\nAmong them are Uvs Nuur, led by Darkhan Avarga N. Batsuur, APU Skytel, led by Dayan Avarga B. Orkhonbayar, and Ev Mongol, led by State Garuda M. Lkhagvagerel. The captains' names signal a competitive and exciting season ahead.\n\nAltantsom is a major team competition in Mongolian national wrestling, and spectators can watch the team contests live at the Wrestling Palace. From the first round onwards, teams will collect points through the season until the best are decided. Wrestling fans are eagerly awaiting Saturday's opening bouts."},
  {id:13, cat:"sport", title:"Монголын баг спорт өрөлтийн Азийн аварга шалгаруулах тэмцээнд оролцохоор Тайланд улсыг зорилоо", titleEn:"Mongolian team heads to Thailand for Asian sport stacking championships", time:"5 цаг", timeEn:"5 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/River%20City%20Bangkok%20Day.jpg?width=760", text:"Спорт өрөлтийн 2026 оны Азийн аварга шалгаруулах тэмцээн 2026 оны арваннэгдүгээр сарын 6-8-ны өдрүүдэд Тайланд улсын Чонбури мужийн Си Рача хотод зохион байгуулагдана. Тус тэмцээнд Монгол Улсаа төлөөлөн нийт 54 тамирчин, багш дасгалжуулагч, эцэг эх, асран хамгаалагчдын хамт нийт 66 хүний бүрэлдэхүүнтэй баг оролцохоор Тайланд улсыг зорьж байна.\n\nАзийн 11 улсын 550 орчим шилдэг тамирчид нэгэн дор цуглаж ур чадвар, хурд, авхаалж самбаагаараа өрсөлдөх бөгөөд олон улсын тэмцээнээс туршлага хуримтлуулах, өөрийн ур чадвараа ахиулахаар манай тамирчид бэлтгэлээ хангаад байна. Спорт өрөлт нь аяга өрөх хурд, нарийвчлал шаарддаг спорт бөгөөд сүүлийн жилүүдэд Монголд хүүхэд, залуучуудын дунд эрчимтэй хөгжиж байна.\n\nМонголын баг тэмцээнд хувийн болон багийн төрлүүдэд өрсөлдөж, олон улсын тавцанд амжилт гаргахыг зорьж байна. Багш дасгалжуулагчид тамирчдынхаа бэлтгэлийг хангаж, олон улсын шүүгчдийн өмнө ур чадвараа харуулах боломжийг чухалчилж байна. Тэмцээний үр дүн Монголын спорт өрөлтийн хөгжилд шинэ түлхэц өгөх төлөвтэй байна.", textEn:"The 2026 Asian Sport Stacking Championships (WSSA) will be held from November 6 to 8 in Si Racha, Chonburi province, Thailand. Mongolia is sending a 66-member delegation, including 54 athletes plus coaches, parents and guardians, to represent the country.\n\nAround 550 top athletes from 11 Asian countries will gather to compete in skill, speed and agility. Mongolian athletes say they have prepared to gain international experience and improve their own skills. Sport stacking, which demands speed and precision in stacking cups, has been growing rapidly among Mongolian children and young people in recent years.\n\nThe Mongolian team will compete in individual and team events, aiming for success on the international stage. Coaches have focused on preparing their athletes to show their skills before international judges. The championship results are expected to give fresh impetus to the development of sport stacking in Mongolia."},
  {id:14, cat:"sport", title:"Дэлхийн аварга шалгаруулах тэмцээнд Монголын гал унтраах техник спортын баг оролцож байна", titleEn:"Mongolian firefighting sport team competes at world championships", time:"6 цаг", timeEn:"6 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Aircraft%20Rescue%20Firefighting%20training.jpg?width=760", text:"Гал унтраах техник спортын Дэлхийн аварга шалгаруулах эрэгтэйчүүдийн 21, эмэгтэйчүүдийн 12 дахь удаагийн тэмцээн 2026 оны арваннэгдүгээр сарын 2-8-ны өдрүүдэд Азербайжан улсын Баку хотод зохион байгуулагдаж байна. Тус тэмцээнд Монгол Улсаа төлөөлөн Онцгой байдлын байгууллагын эмэгтэй шигшээ баг оролцож байна.\n\nБагийн бүрэлдэхүүнд 123 дугаар ангийн Хүний нөөц, дотоод ажил хариуцсан ахлах мэргэжилтэн, ахмад Б.Анхзул, Арчилгаа, усалгаа хариуцсан техникч Б.Хонгорзул нар багтаж байна. Тэд олон улсын тавцанд эх орон, байгууллагаа төлөөлөн ур чадвар, хүч хөдөлмөр, тэсвэр хатуужлаа сорин өрсөлдөж байгаа юм.\n\nГал унтраах техник спорт нь гал унтраах техник хэрэгсэлтэй ажиллах хурд, нарийвчлал, багийн ажиллагааг шалгадаг онцлогтой. Монголын баг энэ тэмцээнд оролцсоноор олон улсын туршлага хуримтлуулж, онцгой байдлын албаны мэргэжлийн ур чадварыг дээшлүүлэх боломж олж байна. Багийн тамирчдад амжилт хүсье гэж Онцгой байдлын байгууллагаас мэдээллээ.", textEn:"The men's 21st and women's 12th Firefighting Sport World Championships are being held from November 2 to 8, 2026, in Baku, Azerbaijan. Mongolia is represented by the women's national team of the National Emergency Management Agency.\n\nThe team includes Captain B. Ankhzul, senior specialist for human resources and internal affairs at Unit 123, and technician B. Khongorzul, responsible for maintenance and watering. They are competing on the international stage, testing their skills, strength and endurance while representing their country and organisation.\n\nFirefighting sport tests speed, precision and teamwork in handling firefighting equipment. By taking part, the Mongolian team gains international experience and a chance to raise the professional skills of the emergency services. The agency has wished its athletes success."},
  {id:15, cat:"soyol", title:"«Монгол Бахархал» сарын аяны хүрээнд «Тэнгэрийн элч Тэмүжин» жүжиг тоглогдоно", titleEn:"Tengeriin Elch Temujin play staged under Mongolian Pride month", time:"6 цаг", timeEn:"6 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Close%20up%20of%20curtain%20and%20stage%20area%20decoration,%20Capitol%20Theatre,%20Swanston%20Street,%20Melbourne,%20Victoria%20(8381667011).jpg?width=760", text:"«Монгол Бахархал – Соёлын бүтээлч сар» аяны хүрээнд «Тэнгэрийн элч Тэмүжин» түүхэн баатарлаг туульсын жүжиг тоглогдоно. Тус жүжгийн уран сайхны удирдагчаар Монгол Улсын Ардын Багш, Урлагийн Гавьяат Зүтгэлтэн, доктор, профессор Н.Ганхуяг, ерөнхий продюсер болон найруулагчаар Монгол Улсын Гавьяат Жүжигчин, Улсын хүүхэд залуучуудын театрын захирал Н.Ариунболд, зохиолчоор Т.Амардаваа, ерөнхий зураачаар Соёлын Тэргүүний Ажилтан Д.Одгэрэл, хөгжмийн зохиолчоор Соёлын Тэргүүний Ажилтан Б.Эрдэнэбат, бүжиг дэглээчээр Соёлын Тэргүүний Ажилтан О.Хэрлэнбаяр нар ажилласан юм.\n\nНийт 150 минут үргэлжлэх энэхүү тайзны цогц бүтээлийн гол болон туслах дүрүүдэд Тэмүжинд СТА А.Оргил, Хадаанд Г.Анун, Жамухад М.Мөнхбат, Сорхон шард П.Анхбаяр, Өүлэн эхэд СТА Э.Уранжаргал, Бөртэд Ш.Бадмаараг зэрэг жүжигчид тоглож, үзэгчдийг түүхийн жимээр аялуулж байна. Жүжиг нь Тэмүжиний залуу нас, нөхөрлөл, тэмцлийн тухай өгүүлж, үндэсний бахархал, түүхэн үнэ цэнийг тайзнаа амилуулжээ.\n\nЖүжиг арваннэгдүгээр сарын 3, 4, 12, 13, 14, 19, 20, 21-ний өдрүүдэд 15:00 цагаас Улсын хүүхэд залуучуудын театрын тайзнаа тоглогдоно. «Монгол Бахархал» сарын аян нь Монголын түүхэн үйл явдлуудын ач холбогдол, үндэсний бахархал, өв соёлын үнэт зүйлсийг олон нийт, хүүхэд залуучуудад таниулах зорилготой бөгөөд энэ жүжиг нь аяны онцлох үйл явдлын нэг болж байна.", textEn:"As part of the Mongolian Pride – Creative Culture Month campaign, the historical heroic epic play Tengeriin Elch Temujin will be staged. Its artistic director is People's Teacher of Mongolia and Merited Artist Dr Prof N. Gankhuyag, its general producer and director is Merited Actor and director of the State Children and Youth Theatre N. Ariunbold, its writer is T. Amardavaa, its chief designer is Cultural Leading Worker D. Odgerel, its composer is Cultural Leading Worker B. Erdenebat, and its choreographer is Cultural Leading Worker O. Kherlenbayar.\n\nThe 150-minute stage production features, among others, STA A. Orgil as Temujin, G. Anun as Khadaan, M. Munkhbat as Jamukha, P. Ankhbayar as Sorkhon Shar, STA E. Uranjargal as Uulen Ekh, and Sh. Badmaarakh as Borte, taking audiences on a journey through history. The play tells of Temujin's youth, friendships and struggles, bringing national pride and historical values to life on stage.\n\nThe play will be performed at 15:00 on November 3, 4, 12, 13, 14, 19, 20 and 21 at the State Children and Youth Theatre. The Mongolian Pride month campaign aims to introduce the public, children and young people to the significance of Mongolian historical events, national pride and cultural heritage values, and this play is one of its highlight events."},
  {id:16, cat:"soyol", title:"«Судар сахигч» хүүхдийн кино төсөл хэрэгжиж байна", titleEn:"Sudar Sakhigch children's film project under way", time:"7 цаг", timeEn:"7 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Giant%20Puppet%20Shows%20by%20Ishara%20Puppet%20Theatre%20Trust%20during%20Youth%20Festival%202011%20at%20CP,%20Delhi%20IMG%208308%2016.jpg?width=760", text:"«Монгол туургатан» олон улсын төслийн хүрээнд Монголын түүх, үндэсний өв соёл, уламжлалт мэдлэг, үнэт зүйлсийг хүүхэд, залууст сонирхолтой, хүртээмжтэй хэлбэрээр сурталчлан таниулах зорилгоор «Судар сахигч» хуруу хүүхэлдэйн хүүхдийн кино төслийг хэрэгжүүлж байна.\n\nЖил бүр уламжлал болгон Соёл, спорт, аялал жуулчлал, залуучуудын яам, Засгийн газрын хэрэгжүүлэгч агентлаг Соёл урлагийн газраас зохион байгуулдаг «Соёлын бүтээлч сар»-ын хүрээнд энэхүү төслийг Соёлын өвийн үндэсний төвийн «Өв эрдэнэ» театрт 2026 оны арваннэгдүгээр сарын 6-ны өдөр нээж буй бөгөөд кино төслийн үзэл санаа, зорилго, нийгэм, соёлын ач холбогдлыг олон нийтэд танилцуулж, хүүхэд залуучуудын үндэсний өв соёлын талаарх мэдлэг, ойлголтыг нэмэгдүүлэхэд хувь нэмэр оруулах юм.\n\nУг кино нь Монголын түүх, соёлын өвийг адал явдалт, уран сэтгэмжит үйл явдалтай хослуулан, хүүхэд залуучуудад эх түүхээрээ бахархах, өв соёлоо хайрлан хамгаалах, үндэсний үнэт зүйлсээ танин мэдэх, өвлөн уламжлуулахын ач холбогдлыг ойлгуулахад чиглэж буйгаараа онцлог юм. Хүүхэлдэйн киноны хэлбэр нь бага насны үзэгчдэд түүхийг ойртуулж, соёлын өвийг хөгжилтэй, ойлгомжтойгоор хүргэх давуу талтай гэж зохион байгуулагчид үзэж байна.", textEn:"Under the international Mongol Tuurgatan project, the Sudar Sakhigch finger-puppet children's film project is being implemented to promote Mongolian history, national heritage, traditional knowledge and values to children and young people in an engaging and accessible form.\n\nAs part of the annual Cultural Creative Month organised by the Ministry of Culture, Sports, Tourism and Youth and the Culture and Arts Agency, the project will be launched on November 6, 2026, at the Ov Erdene Theatre of the National Centre for Cultural Heritage. The launch will present the film project's concept, goals and social and cultural significance to the public, and help increase children and young people's knowledge and understanding of national heritage.\n\nThe film combines Mongolian history and cultural heritage with an adventurous, imaginative story, aiming to help children and young people take pride in their history, cherish and protect their heritage, and understand the importance of learning and passing on national values. Organisers say the puppet-film form brings history closer to young audiences and presents cultural heritage in a fun and understandable way."},
  {id:17, cat:"tech", title:"«AI Changemakers 100x100» хөтөлбөрт 200 залуу хамрагдаж, хиймэл оюуны ур чадвар эзэмшинэ", titleEn:"AI Changemakers 100x100 to train 200 young people in artificial intelligence", time:"7 цаг", timeEn:"7 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Artificial%20Intelligence%20(AI)%20and%20Robotics%20exhibition%20at%20the%20Heinz%20Nixdorf%20MuseumsForum.jpg?width=760", text:"Олон улсын түвшний хиймэл оюуны манлайлагчдыг бэлтгэх «AI Changemakers 100x100» хөтөлбөр зарлагдлаа. AI Academy Asia-аас залуучуудын технологийн ур чадварыг дээшлүүлж, хиймэл оюуны салбарт өрсөлдөх чадварыг нэмэгдүүлэх зорилготой уг хөтөлбөрийг гурав дахь удаагаа зохион байгуулж байна.\n\nХөтөлбөрт улс даяар 25-40 насны 100 залуу мэргэжилтэн, их, дээд сургуулийн 100 оюутан, нийт 200 оролцогчийг сонгон шалгаруулж, 2026 оны арваннэгдүгээр сарын 7-ноос арванхоёрдугаар сарын 26-ны өдрийг хүртэл долоон долоо хоногийн хугацаанд хиймэл оюуны чиглэлээр системтэй бэлтгэнэ. Сургалт цахим хэлбэрээр явагдаж, 20 цахим хичээл бүхий хөтөлбөрийг багтаасан бөгөөд шалгарсан оролцогчдод үнэ төлбөргүй байна. Хөтөлбөрийн гол цөм нь Capstone төсөл бөгөөд 3-4 хүний бүрэлдэхүүнтэй багууд өөрсдийн ажил, салбар, сургуулийн бодит асуудлыг сонгож, хиймэл оюуны шийдэл бүтээн арванхоёрдугаар сарын 26-ны төгсөлтийн Demo Day дээр биечлэн хамгаална.\n\nЭнэхүү хөтөлбөр нь тус байгууллагаас өмнө нь амжилттай хэрэгжүүлсэн «AI for Women 100x100», «Үндэсний Хиймэл Оюуны Аян» төслүүдийн туршлагад тулгуурлан, Олон улсын цахилгаан холбооны байгууллагын «AI Skills Coalition» эвслийн хүрээнд, AI Academy Asia-ийн санаачилгаар, ерөнхий ивээн тэтгэгч Нэткапитал Санхүүгийн Групп болон хамтран ивээн тэтгэгч Монложистикс группийн дэмжлэгтэйгээр зохион байгуулагдаж байна. Өмнөх төслүүд нь өнгөрсөн есдүгээр сард НҮБ-аас зохион байгуулдаг «Digital@UNGA 2026» шалгаруулалтад 146 орны 1,500 төслөөс шалгарч, дэд байр эзэлсэн түүхэн амжилт үзүүлсэн билээ. Зохион байгуулагчдын үзэж буйгаар дэлхийн эдийн засгийн форумаас хиймэл оюун 97 сая шинэ ажлын байр бий болгоно гэж тооцоолсон бол ОУВС нийт ажлын байрны 40 хувьд нөлөөлнө гэж тооцоолжээ. Иймд Монголын залуус хиймэл оюуныг хэрэглэгч төдийгүй бүтээгчийн түвшинд эзэмших шаардлагатай байна.", textEn:"The AI Changemakers 100x100 programme to train international-level artificial intelligence leaders has been announced. Organised for the third time by AI Academy Asia, it aims to raise young people's technological skills and competitiveness in AI.\n\nThe programme will select 100 young professionals aged 25-40 and 100 university students from across the country, 200 participants in total, and train them systematically in AI over seven weeks, from November 7 to December 26, 2026. Training is online, includes 20 e-lessons, and is free for selected participants. Its core is a Capstone project: teams of 3-4 people choose a real problem from their work, sector or school, build an AI solution, and defend it in person at the graduation Demo Day on December 26.\n\nThe programme builds on the organisation's earlier AI for Women 100x100 and National AI Campaign projects, and is run within the International Telecommunication Union's AI Skills Coalition, on AI Academy Asia's initiative, with Netcapital Financial Group as general sponsor and Monlogistics Group as co-sponsor. Those earlier projects achieved a historic result at the UN's Digital@UNGA 2026 competition last September, placing second among 1,500 projects from 146 countries. Organisers note that the World Economic Forum estimates AI will create 97 million new jobs, while the IMF estimates it will affect 40 percent of all jobs, so Mongolian young people need to master AI as creators, not just users."},
  {id:18, cat:"oron-nutag", title:"Ховд: Нутгийн 54.7 хувьд зудын эрсдэл их байна", titleEn:"Khovd: dzud risk high across 54.7 percent of the province", time:"8 цаг", timeEn:"8 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Snow%20in%20Mongolia%20(MODIS%202017-01-19).jpg?width=760", text:"Зудын урьдчилсан төлөв мэдээгээр 2026 оны арваннэгдүгээр сард Ховд аймгийн нутаг дэвсгэрийн 54.7 хувьд өвөлжилт хүндрэх эрсдэлтэй байна. Үнэлгээгээр аймгийн нийт нутгийн 16.7 хувьд зудын нэн их, 38 хувьд их, 41.9 хувьд дунд, 3.4 хувьд бага эрсдэлтэй гэж дүгнэжээ. Өөрөөр хэлбэл, аймгийн хэмжээнд зудын эрсдэлгүй нутаг байхгүй байна.\n\nСумдаар авч үзвэл Ховд, Буянт, Мянгад, Дуут, Мөнххайрхан сумын нутгаар зудын эрсдэл нэн их, Эрдэнэбүрэн, Дөргөн, Чандмань, Дарви суманд их түвшинд үнэлэгджээ. Харин Алтай, Үенч, Булган, Цэцэг, Зэрэг, Мөст сумын нутгаар дунд болон бага эрсдэлтэй байна. Энэ жил Ховд аймгийн хэмжээнд 8,000 гаруй малчин өрхийн 3.1 сая гаруй мал өвөлжинө.\n\nИймд малчид, орон нутгийн удирдлагууд цаг уурын байгууллагаас гаргадаг богино, дунд, урт хугацааны урьдчилсан мэдээ болон тухай бүр шинэчлэн гаргах зудын төлөвийг тогтмол авч ашиглах, нөхцөл байдал хүндэрсэн үед авах арга хэмжээг урьдчилан тооцоолохыг мэргэжлийн байгууллагаас зөвлөж байна. Өвс тэжээлийн нөөц, малын хашаа хороог бэлтгэх, цаг агаарын мэдээг тогтмол дагах нь өвөлжилтийг хүндрэлгүй даван туулах гол нөхцөл болж байна.", textEn:"According to the preliminary dzud outlook, wintering is at risk of difficulty across 54.7 percent of Khovd province in November 2026. The assessment rates 16.7 percent of the province at extremely high risk, 38 percent at high risk, 41.9 percent at moderate risk and 3.4 percent at low risk. In other words, there is no part of the province without dzud risk.\n\nBy soum, Khovd, Buyant, Myangad, Duut and Monkhkhairkhan are rated at extremely high risk, while Erdeneburen, Dorgon, Chandmani and Darvi are rated high. Altai, Uench, Bulgan, Tsetseg, Zereg and Most are rated moderate or low. This year more than 8,000 herder households and over 3.1 million livestock will winter in Khovd province.\n\nProfessionals therefore advise herders and local authorities to regularly use short-, medium- and long-term forecasts from the meteorological service, as well as updated dzud outlooks, and to plan in advance the measures to take if conditions worsen. Preparing fodder reserves and livestock shelters and following weather forecasts regularly are key to getting through winter without severe difficulty."},
  {id:19, cat:"oron-nutag", region:"dornod", title:"Дорнод: Зүүн нутгаар цас, цасан шуурга шуурч, малчид бэлтгэлээ хангахыг анхаарууллаа", titleEn:"Dornod: snow and blizzards in the east, herders urged to prepare", time:"8 цаг", timeEn:"8 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Mong%20winter1%20-%20panoramio.jpg?width=760", text:"Арваннэгдүгээр сарын 4-5-нд нутгийн зүүн хэсгээр цас орж, зөөлөн цасан шуурга шуурах төлөвтэй байгаа тул Дорнод зэрэг зүүн аймгуудын малчид, иргэдэд цаг уурын байгууллагаас онцгой анхааруулга хүргүүллээ. Дорнодын хойд сумдаар шөнөдөө, зүүн сумдаар 5-нд цас орж, шуурга шуурах төлөвтэй байна. Мөн Хөвсгөлийн баруун, Завхан, Сүхбаатарын зарим сумдаар 0.0-1.0 мм цас орж, явган шуурга шуурна.\n\nЦас, шуурганы үед зам, даваа гүвээнд үзэгдэх орчин хязгаарлагдаж, халтиргаа гулгаа, мөстөлт үүсэх эрсдэлтэй тул тээвэрчид хурдаа тохируулж, замын хөдөлгөөнд болгоомжтой оролцох шаардлагатай. Салхи нутгийн зүүн хэсгээр баруун өмнөөс хойш эргэж, бусад нутгаар баруунаас секундэд 5-10 метр, Алтайн уулархаг нутаг, говь, тал, хээрийн нутгаар секундэд 13-15 метр хүрч ширүүснэ. Монгол-Алтай, Хөвсгөл, Хэнтийн уулархаг нутаг, Завхан, Заг-Байдраг голын эх, Хүрэнбэлчир орчим, Дорнод-Дарьгангын тал нутгаар шөнөдөө 2-7 градус хүйтэн байх төлөвтэй байна.\n\nМалчид малаа хашаа, хороондоо оруулж, өвс тэжээлийн нөөцөө шалгаж, цаг агаарын богино, дунд хугацааны урьдчилсан мэдээг тогтмол авч ашиглахыг мэргэжлийн байгууллагаас зөвлөж байна. Өвөлжилтийн бэлтгэл хангагдаагүй айл өрхөд цас, хүйтэн нь хүндрэл учруулж болзошгүй тул орон нутгийн удирдлагууд малчдад тусламж, мэдээлэл хүргэх ажлыг эрчимжүүлэх шаардлагатай байна. Улаанбаатар хот орчмоор үүлшинэ, цас орохгүй, салхи баруунаас секундэд 5-10 метр, 1-3 градус дулаан байх төлөвтэй байна.", textEn:"With snow and light blizzards forecast for eastern areas on November 4-5, the meteorological service has issued a special warning to herders and residents in eastern provinces including Dornod. Snow is expected overnight in northern soums of Dornod and on November 5 in its eastern soums, with blizzard conditions. Snow of 0.0-1.0 mm and ground blizzards are also expected in parts of western Khuvsgul, Zavkhan and Sukhbaatar.\n\nDuring snow and storms, visibility on roads and passes may be limited and slippery, icy conditions may develop, so drivers need to adjust speed and take care. Winds will blow from the southwest turning north in the east and from the west elsewhere at 5-10 metres per second, reaching 13-15 metres per second in the Altai mountains, Gobi, steppe and field areas. Night temperatures of minus 2 to minus 7 degrees are expected in the Mongol-Altai, Khuvsgul and Khentii mountains, the sources of the Zavkhan and Zag-Baidrag rivers, the Khurenbelchir area and the Dornod-Dariganga steppe.\n\nHerders are advised to bring livestock into shelters, check fodder reserves, and regularly follow short- and medium-term weather forecasts. Households that have not fully prepared for winter may face difficulties from snow and cold, so local authorities need to step up help and information for herders. Around Ulaanbaatar it will be cloudy with no snow, winds from the west at 5-10 metres per second, and temperatures of 1-3 degrees above zero."}
];
function aTitle(a){ return LANG === "en" ? (a.titleEn || a.title) : a.title; }
function aTime(a){ return LANG === "en" ? (a.timeEn || a.time) : a.time; }
function aText(a){ if(a.text) return LANG === "en" ? (a.textEn || a.text) : a.text; return SAMPLE_TEXT[LANG][a.id === 1 ? "long" : "short"]; }
function aRegion(a){ return a.region ? ((REGIONS[LANG] && REGIONS[LANG][a.region]) || a.region) : ""; }

// ===== Ханш · Цаг агаар (өдөр бүр шинэчлэгдэнэ; цаг агаарыг Open-Meteo-гоос шууд татна) =====
const RATES = {date:"2026-11-05", items:[
  {code:"USD", mnt:3600.04, chg:1}, {code:"EUR", mnt:4046.08, chg:1}, {code:"JPY", mnt:22.77, chg:-1},
  {code:"CNY", mnt:539.11, chg:-1}, {code:"KRW", mnt:2.69, chg:0}, {code:"RUB", mnt:43.94, chg:-1}, {code:"GBP", mnt:4851.95, chg:1}
]};
let WEATHER = [
  {city:"Улаанбаатар", cityEn:"Ulaanbaatar", lat:47.9212, lon:106.9186, tz:"Asia/Ulaanbaatar", temp:-11, code:1},
  {city:"Токио", cityEn:"Tokyo", lat:35.6762, lon:139.6503, tz:"Asia/Tokyo", temp:13, code:53},
  {city:"Сөүл", cityEn:"Seoul", lat:37.5665, lon:126.978, tz:"Asia/Seoul", temp:9, code:51},
  {city:"Бээжин", cityEn:"Beijing", lat:39.9042, lon:116.4074, tz:"Asia/Shanghai", temp:5, code:45},
  {city:"Москва", cityEn:"Moscow", lat:55.7558, lon:37.6173, tz:"Europe/Moscow", temp:1, code:3}
];
function wIcon(code){
  if(code === 0) return "☀️";
  if(code === 1) return "🌤️";
  if(code === 2) return "⛅";
  if(code === 3) return "☁️";
  if(code === 45 || code === 48) return "🌫️";
  if(code === 51 || code === 53 || code === 55 || code === 80) return "🌦️";
  if(code === 56 || code === 57 || code === 61 || code === 63 || code === 65 || code === 66 || code === 67 || code === 81 || code === 82) return "🌧️";
  if(code === 71 || code === 73 || code === 75 || code === 77 || code === 85 || code === 86) return "❄️";
  if(code >= 95) return "⛈️";
  return "🌡️";
}
function fmtRate(v){
  if(v >= 100) return Math.round(v).toLocaleString("en-US");
  return v.toFixed(2);
}
function renderData(){
  const parts = [];
  RATES.items.forEach(r=>{
    let arrow = "";
    if(r.chg > 0) arrow = ' <span class="up">▲</span>';
    else if(r.chg < 0) arrow = ' <span class="down">▼</span>';
    parts.push(`<span class="tk"><b>${r.code}</b> ${fmtRate(r.mnt)}₮${arrow}</span>`);
  });
  WEATHER.forEach(w=>{
    const name = LANG === "en" ? w.cityEn : w.city;
    const t = w.temp > 0 ? "+" + w.temp : "" + w.temp;
    parts.push(`<span class="tk">${wIcon(w.code)} ${name} ${t}°C</span>`);
  });
  const html = parts.join('<span style="color:#666">•</span>');
  const track = document.getElementById("tickerTrack");
  if(track) track.innerHTML = html + '<span style="color:#666">•</span>' + html + '<span style="color:#666">•</span>';
  const usd = RATES.items.find(r=>r.code === "USD");
  const ue = document.getElementById("usdText");
  if(ue && usd) ue.textContent = "USD: " + fmtRate(usd.mnt) + "₮";
  const wt = document.getElementById("weatherText");
  const ub = WEATHER[0];
  if(wt && ub) wt.textContent = wIcon(ub.code) + " " + (LANG === "en" ? ub.cityEn : ub.city) + " " + (ub.temp > 0 ? "+" + ub.temp : ub.temp) + "°C";
}
function refreshWeather(){
  WEATHER.forEach((w, idx)=>{
    const url = "https://api.open-meteo.com/v1/forecast?latitude=" + w.lat + "&longitude=" + w.lon + "&current=temperature_2m%2Cweather_code&timezone=" + encodeURIComponent(w.tz);
    fetch(url).then(r=>r.json()).then(d=>{
      if(d && d.current){ WEATHER[idx].temp = Math.round(d.current.temperature_2m); WEATHER[idx].code = d.current.weather_code; renderData(); }
    }).catch(()=>{});
  });
}

